def handle(query, state):
    """
    A file search utility that constructs shell commands from user input.
    Vulnerable to command injection via backtick or $() substitution patterns.
    The search_term parameter is interpolated into a command that searches
    through files in the virtual filesystem.
    """
    vfs = state.get('files', {})

    def run_cmd(argv):
        """Execute a command against the virtual filesystem."""
        if not argv:
            return ''
        cmd = argv[0]
        args = argv[1:]

        if cmd == 'grep':
            if len(args) < 2:
                return 'grep: usage error\n'
            pattern = args[0]
            filepaths = args[1:]
            results = []
            for filepath in filepaths:
                content = vfs.get(filepath)
                if content is None:
                    results.append(f'grep: {filepath}: No such file or directory')
                else:
                    for line in content.split('\n'):
                        if pattern in line:
                            results.append(f'{filepath}: {line}')
            return '\n'.join(results) + '\n' if results else ''
        elif cmd == 'cat':
            out = ''
            for path in args:
                content = vfs.get(path)
                if content is None:
                    out += f'cat: {path}: No such file or directory\n'
                else:
                    out += content
                    if not content.endswith('\n'):
                        out += '\n'
            return out
        elif cmd == 'echo':
            return ' '.join(args) + '\n'
        elif cmd == 'wc':
            if not args:
                return 'wc: no files\n'
            result = 0
            for path in args:
                content = vfs.get(path)
                if content is not None:
                    result += len(content.split('\n'))
            return f'{result}\n'
        else:
            return f'{cmd}: command not found\n'

    def shell_exec(cmdline):
        """Split on pipes and semicolons, executing each segment in sequence.
        Supports backtick command substitution: `command` is replaced with its output."""
        import re
        # First, handle backtick substitution recursively
        def substitute_backticks(text):
            while '`' in text:
                match = re.search(r'`([^`]+)`', text)
                if not match:
                    break
                inner_cmd = match.group(1).strip()
                # Parse the inner command
                inner_argv = inner_cmd.split()
                sub_output = run_cmd(inner_argv)
                # Remove trailing newline from substitution
                sub_output = sub_output.rstrip('\n')
                text = text[:match.start()] + sub_output + text[match.end():]
            return text

        # Apply backtick substitution first
        cmdline = substitute_backticks(cmdline)

        # Then split on semicolons and execute
        output = ''
        for segment in cmdline.split(';'):
            segment = segment.strip()
            if not segment:
                continue
            argv = segment.split()
            output += run_cmd(argv)
        return output

    search_term = (query.get('search') or [''])[0]
    if not search_term:
        body = 'Usage: ?search=<term>\n'
        return 200, {'Content-Type': 'text/plain'}, body

    # Vulnerable: search_term is interpolated unsanitized into the command
    # An attacker can inject backtick commands: search=`cat /etc/secrets`
    cmd = f'echo Search results for: {search_term}'
    output = shell_exec(cmd)

    return 200, {'Content-Type': 'text/plain'}, output
